body:
Context
- We’re adding first-class staged rollouts for Dedicated reserved pools.
- This doc is a working sketch of the control-plane data model (proto-ish), example configs, and DB/state handling.
- Target: unblock ENG-5121 (persistence/migrations), ENG-5122 (CRUD + approval APIs), and routing integration (weights).

Primary requirements this model needs to satisfy
1) Versioned rollout plan config (immutable history) + current active plan pointer per pool/route.
2) State machine for execution (stage progression, holds, rollbacks) decoupled from plan definition.
3) Idempotent APIs and safe concurrency: avoid race between approvals and evaluator ticks.
4) Auditability: who did what, when, and what plan version they acted on.
5) Deterministic traffic allocation for a Dedicated pool at any point-in-time.

Non-goals (for this sketch)
- Full experiment framework / multi-armed bandit.
- Complex per-request semantic quality gating.

Glossary / terms
- RolloutPlan: desired staged rollout definition (stages, gates, approval policies) for a given pool/route/model change.
- Plan version: immutable snapshot of a plan definition. Updates create a new version.
- Execution: runtime state for a given plan version applied to a pool, including current stage + gate evaluation results.
- Gate: condition evaluated over a window, producing PASS/FAIL/UNKNOWN.


A. Proto schema sketch (control-plane)
NOTE: naming here is approximate; actual packages may differ. The key is the shape.

// proto3

message RolloutPlan {
  string plan_id = 1;                 // ULID/UUID
  string tenant_id = 2;               // Dedicated tenant
  string pool_id = 3;                 // Reserved pool identifier

  // Optional: per-route rollouts (if we support multiple routes per pool).
  // If not needed for v1, keep as empty or "default".
  string route_id = 4;

  // What change is being rolled out.
  RolloutTarget target = 5;

  // Active definition snapshot pointer.
  int64 current_version = 6;

  // Status of the plan lifecycle (definition-side, not execution-side).
  RolloutPlanStatus status = 7;       // DRAFT/ACTIVE/ARCHIVED

  // Metadata
  string created_by = 8;
  string created_at = 9;             // RFC3339
  string last_modified_by = 10;
  string last_modified_at = 11;      // RFC3339
}

enum RolloutPlanStatus {
  ROLLOUT_PLAN_STATUS_UNSPECIFIED = 0;
  ROLLOUT_PLAN_STATUS_DRAFT = 1;
  ROLLOUT_PLAN_STATUS_ACTIVE = 2;
  ROLLOUT_PLAN_STATUS_ARCHIVED = 3;
}

message RolloutTarget {
  // One of these is required. In Dedicated most changes will be "model+runtime config".
  string model_id = 1;               // e.g., "llama-3.1-70b"
  string model_version = 2;          // e.g., "2025-01-10.1" or git SHA for compiled artifact

  // Runtime/serving config that might affect perf.
  string runtime_profile_id = 3;     // e.g., "tp2-fp8-batch32"

  // Rollout reason / ticket.
  string change_request = 4;         // e.g., "ENG-5121" or internal change id
}

message RolloutPlanVersion {
  string plan_id = 1;
  int64 version = 2;                 // monotonic per plan_id

  RolloutDefinition definition = 3;

  string created_by = 4;
  string created_at = 5;             // RFC3339
  string comment = 6;                // freeform
}

message RolloutDefinition {
  // Execution policy.
  StageAdvancementPolicy advancement = 1;

  // Ordered stages. Stage IDs are stable within a version.
  repeated RolloutStage stages = 2;

  // Optional: global defaults for gates.
  EvaluationDefaults eval_defaults = 3;

  // Optional: safety constraints
  SafetyConstraints safety = 4;
}

message StageAdvancementPolicy {
  bool requires_manual_approval_each_stage = 1;

  // If true, evaluator can advance automatically if gates pass AND policy allows.
  // For Dedicated beta we likely default to false beyond stage 0->1.
  bool allow_auto_advance = 2;

  // If true, failures trigger automatic rollback (to previous stable target)
  // vs default "hold".
  bool allow_auto_rollback = 3;
}

message EvaluationDefaults {
  int64 evaluation_window_seconds = 1;    // e.g., 600
  int64 min_sample_size = 2;             // e.g., 1000 requests
  int64 metrics_freshness_seconds = 3;   // e.g., 120
}

message SafetyConstraints {
  // Guardrails in addition to gates, e.g., headroom requirements.
  double min_headroom_fraction = 1;  // e.g., 0.15 => must keep 15% capacity headroom

  // If true, missing metrics forces HOLD rather than treating as PASS.
  bool fail_safe_on_missing_metrics = 2;
}

message RolloutStage {
  string stage_id = 1;                 // unique within version, e.g., "s0", "s1" or ULID
  string name = 2;                     // "5%" / "25%" / "100%"

  // Traffic allocation for this stage.
  // For v1 we treat as percent of total traffic to "new" target.
  // Old target gets (1 - weight).
  double weight_new = 3;               // 0.0 to 1.0

  // Minimum time spent in stage before eligible to advance.
  int64 min_duration_seconds = 4;

  // Gates to evaluate in this stage.
  repeated Gate gates = 5;

  // If true, stage requires explicit approval to enter.
  // Overrides global policy if needed.
  bool requires_manual_approval = 6;
}

message Gate {
  string gate_id = 1;
  GateType type = 2;

  // Gate evaluation parameters (window, threshold, comparison)
  GateSpec spec = 3;
}

enum GateType {
  GATE_TYPE_UNSPECIFIED = 0;
  GATE_TYPE_P95_LATENCY_MS = 1;
  GATE_TYPE_5XX_RATE = 2;
  GATE_TYPE_TIMEOUT_RATE = 3;
  GATE_TYPE_QUEUE_DEPTH = 4;
  GATE_TYPE_GPU_UTILIZATION = 5;
  // Optional later: quality regression
  GATE_TYPE_QUALITY_SCORE = 6;
}

message GateSpec {
  // Window may override defaults
  int64 evaluation_window_seconds = 1;

  // Metric must be fresher than this.
  int64 metrics_freshness_seconds = 2;

  // Minimum samples required to make a PASS/FAIL decision.
  int64 min_sample_size = 3;

  ComparisonOp op = 4;
  double threshold = 5;

  // If missing/late metrics
  MissingDataPolicy missing_data = 6;
}

enum ComparisonOp {
  COMPARISON_OP_UNSPECIFIED = 0;
  COMPARISON_OP_LT = 1;
  COMPARISON_OP_LTE = 2;
  COMPARISON_OP_GT = 3;
  COMPARISON_OP_GTE = 4;
}

enum MissingDataPolicy {
  MISSING_DATA_POLICY_UNSPECIFIED = 0;
  MISSING_DATA_POLICY_HOLD = 1;     // default for Dedicated
  MISSING_DATA_POLICY_FAIL = 2;
  MISSING_DATA_POLICY_PASS = 3;     // not recommended
}


Execution/state schema sketch
We should not conflate the plan definition (versioned) with execution state (mutable).

message RolloutExecution {
  string execution_id = 1;          // unique per (plan_id, version) start
  string plan_id = 2;
  int64 plan_version = 3;

  ExecutionStatus status = 4;       // RUNNING/HOLD/ABORTED/ROLLED_BACK/COMPLETED

  // Current stage pointer
  string current_stage_id = 5;

  // Timestamps for progression
  string started_at = 6;
  string updated_at = 7;

  // Optional: stable baseline target (for rollback)
  RolloutTarget baseline_target = 8;

  // Rollout-level failure reason (if in HOLD)
  string hold_reason = 9;
}

enum ExecutionStatus {
  EXECUTION_STATUS_UNSPECIFIED = 0;
  EXECUTION_STATUS_RUNNING = 1;
  EXECUTION_STATUS_HOLD = 2;
  EXECUTION_STATUS_ABORTED = 3;
  EXECUTION_STATUS_ROLLED_BACK = 4;
  EXECUTION_STATUS_COMPLETED = 5;
}

message GateEvaluationResult {
  string execution_id = 1;
  string stage_id = 2;
  string gate_id = 3;

  GateEvalStatus status = 4;        // PASS/FAIL/UNKNOWN
  string evaluated_at = 5;

  // For debugging / audit
  string query = 6;                // human-readable query or template id
  string observed_value = 7;       // store as string to avoid float formatting fights
  string threshold = 8;
  string details = 9;              // error/missing metrics detail
}

enum GateEvalStatus {
  GATE_EVAL_STATUS_UNSPECIFIED = 0;
  GATE_EVAL_STATUS_PASS = 1;
  GATE_EVAL_STATUS_FAIL = 2;
  GATE_EVAL_STATUS_UNKNOWN = 3;
}

message RolloutApprovalEvent {
  string event_id = 1;             // ULID
  string execution_id = 2;
  string plan_id = 3;
  int64 plan_version = 4;

  string stage_id = 5;             // which stage transition is being approved

  ApprovalAction action = 6;       // APPROVE_STAGE / ABORT / RESUME / ROLLBACK
  string actor = 7;                // user/service principal
  string actor_type = 8;           // "human" | "service"
  string reason = 9;
  string created_at = 10;

  // For idempotency
  string request_id = 11;
}

enum ApprovalAction {
  APPROVAL_ACTION_UNSPECIFIED = 0;
  APPROVAL_ACTION_APPROVE_STAGE = 1;
  APPROVAL_ACTION_ABORT = 2;
  APPROVAL_ACTION_RESUME = 3;
  APPROVAL_ACTION_ROLLBACK = 4;
}

Notes on IDs
- plan_id: ULID preferred (sortable); UUID is fine.
- stage_id and gate_id: stable within a plan version. We should not allow editing a version in-place.
- execution_id: ULID per run, because same plan version could theoretically be re-executed (rare but useful in testing).
- request_id: required for mutating endpoints to enforce idempotency.


B. Example JSON configs (operator-facing / API payload)
These are example request payloads; not necessarily stored 1:1.

